package Picture;

import java.io.ByteArrayOutputStream;
import java.io.File;
import java.io.IOException;
import java.util.ArrayList;

public class MakePicture {

    protected int HEIGHT_TOTAL;
    protected int WIDTH_TOTAL;

    /**
     *
     * @return Array of bytes with the header for the bmp file
     */
    private byte[] makeHeader() {
        // HEADER
        // THE HARDCODED BYTES WERE GENERATED BY CHATGPT CLANKER IM LAZY
        //
        // TO CHANGE RESOLUTION SEARCH FOR COMMENTED BYTES
        // THE BYTES CHANGED NEED TO BE IN LITTLE ENDIAN

        // CONVERSION FROM INT TO LITTLE ENDIAN BYTE FROM GEEKSSHARED.NET
        //
        // TAKES AN INTEGER AND SPLITS IT INTO 4 BLOCKS OF 1 BYTE EACH -> 4 BYTES

        // EXAMPLE
        // WIDTH = 1280 = 0x00000500
        // HEIGHT = 720 = 0x000002D0

        byte[] widthB = new byte[4];
        widthB[0] = (byte) (WIDTH_TOTAL & 0xff);
        widthB[1] = (byte) (WIDTH_TOTAL >> 8 & 0xff);
        widthB[2] = (byte) (WIDTH_TOTAL >> 16 & 0xff);
        widthB[3] = (byte) (WIDTH_TOTAL >> 24 & 0xff);

        byte[] heightB = new byte[4];
        heightB[0] = (byte) (HEIGHT_TOTAL & 0xff);
        heightB[1] = (byte) (HEIGHT_TOTAL >> 8 & 0xff);
        heightB[2] = (byte) (HEIGHT_TOTAL >> 16 & 0xff);
        heightB[3] = (byte) (HEIGHT_TOTAL >> 24 & 0xff);

        return new byte[]{
                // FILE HEADER
                (byte) 0x42, // B
                (byte) 0x4D, // M

                (byte) 0x36,
                (byte) 0x30,
                (byte) 0x2A,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x36,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x28,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,

                widthB[0], // X
                widthB[1],
                widthB[2],
                widthB[3],

                heightB[0], // Y
                heightB[1],
                heightB[2],
                heightB[3],

                (byte) 0x01,
                (byte) 0x00,
                (byte) 0x18,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x30,
                (byte) 0x2A,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00,
                (byte) 0x00
        };
    }

    /**
     *
     * @param f File to read
     * @throws IOException
     */
    public void makeFile(File f) throws IOException {
        PixelData pix = new PixelData(f);
        File picture = new File("test.bmp");

        // https://stackoverflow.com/questions/10061029/how-to-make-bmp-image-from-pixel-byte-array-in-java

        ByteArrayOutputStream picData = new ByteArrayOutputStream();

        byte[] header = makeHeader(); // CREATES A HEADER WITH A SET RES
        picData.write(header); // ADDS THE HEADER TO THE OutputStream

        picData.close();
    }


}
